// Original questions for Intermediate Reading, Advanced Prose, Advanced Poetry,
// and Advanced Reading. Original questions for Latin Launchpad.

addQuestions([
  annualExamQ('ir-tib-01', 'intermediate-reading', 'reading', 'Where did the farmer live?', ['Near the Tiber.', 'In Ostia only.', 'On an island.', 'In a school.'], 'Near the Tiber.', 'Prope Tiberim means near the Tiber. Habitabat means he was living.', { passageId: 'intermediate-reading-tiber', order: 1 }),
  annualExamQ('ir-tib-02', 'intermediate-reading', 'reading', 'What did he do every day?', ['He went down to the river.', 'He sailed to Egypt.', 'He taught a class.', 'He built a bridge.'], 'He went down to the river.', 'Cotidie means every day, and ad flumen descendebat means he used to go down to the river.', { passageId: 'intermediate-reading-tiber', order: 2 }),
  annualExamQ('ir-tib-03', 'intermediate-reading', 'reading', 'When the water was high, what was he unwilling to do?', ['Leave the fields.', 'Sell the grain.', 'Trust his son.', 'Enter Rome.'], 'Leave the fields.', 'Agros relinquere nolebat means he was unwilling to leave the fields. Cum aqua alta esset sets the scene when the water was high.', { passageId: 'intermediate-reading-tiber', order: 3 }),
  annualExamQ('ir-tib-04', 'intermediate-reading', 'reading', 'What does Gaius want his father to do?', ['Come with him to the city so they can sell grain.', 'Stay away from the river forever.', 'Join the army.', 'Hide the ships.'], 'Come with him to the city so they can sell grain.', 'Veni mecum ad urbem means come with me to the city. Ut frumentum vendamus gives the purpose.', { passageId: 'intermediate-reading-tiber', order: 4 }),
  annualExamQ('ir-tib-05', 'intermediate-reading', 'reading', 'Ut frumentum vendamus means', ['so that we may sell the grain.', 'because the grain was sold.', 'do not sell the grain.', 'the grain sells us.'], 'so that we may sell the grain.', 'Ut plus the subjunctive vendamus expresses purpose: so that we may sell.', { passageId: 'intermediate-reading-tiber', order: 5 }),
  annualExamQ('ir-tib-06', 'intermediate-reading', 'reading', 'Why is filio dative in "qui filio credebat"?', ['Credo takes the dative for the person trusted.', 'Filius is the subject.', 'The verb is passive.', 'Filio shows the place to which.'], 'Credo takes the dative for the person trusted.', 'Credebat means he trusted. The person trusted, his son, is dative: filio.', { passageId: 'intermediate-reading-tiber', order: 6 }),
  annualExamQ('ir-tib-07', 'intermediate-reading', 'reading', 'What do they see while they travel?', ['Many ships in the river.', 'A she-wolf.', 'The Minotaur.', 'A wooden horse.'], 'Many ships in the river.', 'Multas naves in flumine videbant means they kept seeing many ships in the river.', { passageId: 'intermediate-reading-tiber', order: 7 }),
  annualExamQ('ir-tib-08', 'intermediate-reading', 'reading', 'What does Gaius ask?', ['Where the ships had come from.', 'Whether Orpheus looked back.', 'What the bath costs.', 'Who the consul is.'], 'Where the ships had come from.', 'Unde naves venissent means where the ships had come. Venissent is subjunctive in the indirect question.', { passageId: 'intermediate-reading-tiber', order: 8 }),
  annualExamQ('ir-tib-09', 'intermediate-reading', 'reading', 'What does the father say the ships are doing?', ['Carrying grain from Ostia.', 'Leaving Rome empty.', 'Sinking in the bath.', 'Carrying soldiers to Troy.'], 'Carrying grain from Ostia.', 'Eas ex Ostia frumentum portare means that they were carrying grain from Ostia. Eas refers to the ships.', { passageId: 'intermediate-reading-tiber', order: 9 }),
  annualExamQ('ir-tib-10', 'intermediate-reading', 'reading', 'Eas in the father\'s answer refers to', ['the ships.', 'the fields.', 'Gaius and his father.', 'the coins.'], 'the ships.', 'Eas is feminine accusative plural, matching naves. It is the subject of the infinitive portare.', { passageId: 'intermediate-reading-tiber', order: 10 }),
  annualExamQ('ir-tib-11', 'intermediate-reading', 'reading', 'Where do they stay at night?', ['In an inn.', 'On the bridge.', 'In the senate.', 'Under the holm-oak.'], 'In an inn.', 'In caupona means in an inn. Nocte means at night.', { passageId: 'intermediate-reading-tiber', order: 11 }),
  annualExamQ('ir-tib-12', 'intermediate-reading', 'reading', 'When do they enter Rome?', ['At dawn.', 'At midnight.', 'In the middle of winter only.', 'After the baths close.'], 'At dawn.', 'Prima luce means at first light, at dawn. Romam intraverunt means they entered Rome.', { passageId: 'intermediate-reading-tiber', order: 12 }),
  annualExamQ('ir-tib-13', 'intermediate-reading', 'reading', 'Why does Romam have no preposition?', ['The name of a city uses the accusative alone for place to which.', 'Romam is ablative.', 'The verb is passive.', 'Romam is a vocative.'], 'The name of a city uses the accusative alone for place to which.', 'Romam means to Rome. Cities and towns do not need ad for this meaning. Ad urbem earlier used ad because urbs is a common noun.', { passageId: 'intermediate-reading-tiber', order: 13 }),
  annualExamQ('ir-tib-14', 'intermediate-reading', 'reading', 'What did they do with the grain in Rome?', ['They sold it.', 'They burned it.', 'They gave it to Orpheus.', 'They left it on the ship.'], 'They sold it.', 'Frumentum vendiderunt means they sold the grain. Vendiderunt is perfect.', { passageId: 'intermediate-reading-tiber', order: 14 }),
  annualExamQ('ir-tib-15', 'intermediate-reading', 'reading', 'Why was Gaius happy?', ['Because they had sold the grain well.', 'Because the river was still high.', 'Because he lost the money.', 'Because school was closed.'], 'Because they had sold the grain well.', 'Quod frumentum bene vendiderant means because they had sold the grain well. Vendiderant is pluperfect.', { passageId: 'intermediate-reading-tiber', order: 15 }),
  annualExamQ('ir-tib-16', 'intermediate-reading', 'reading', 'Iter faciebant means', ['they were traveling.', 'they were unwilling.', 'they had sold.', 'make a law.'], 'they were traveling.', 'Iter facere means to travel, to make a journey. Faciebant is imperfect, they were making.', { passageId: 'intermediate-reading-tiber', order: 16 }),

  annualExamQ('ir-sch-01', 'intermediate-reading', 'reading', 'Where are the students at the start?', ['In school.', 'At the baths.', 'On a ship.', 'In the underworld.'], 'In school.', 'In schola means in school. Sedebant means they were sitting.', { passageId: 'intermediate-reading-orpheus', order: 1 }),
  annualExamQ('ir-sch-02', 'intermediate-reading', 'reading', 'What are the students doing?', ['Listening to the teacher.', 'Selling grain.', 'Guarding a bridge.', 'Sleeping in the villa.'], 'Listening to the teacher.', 'Magistrum audiebant means they were listening to the teacher. Magistrum is accusative.', { passageId: 'intermediate-reading-orpheus', order: 2 }),
  annualExamQ('ir-sch-03', 'intermediate-reading', 'reading', 'Why does the teacher tell the story of Orpheus?', ['So that the boys might love the poet.', 'So that they might leave school.', 'Because the river was high.', 'To sell a lyre.'], 'So that the boys might love the poet.', 'Ut pueri poetam amarent is a purpose clause: so that the boys might love the poet.', { passageId: 'intermediate-reading-orpheus', order: 3 }),
  annualExamQ('ir-sch-04', 'intermediate-reading', 'reading', 'Whom did Orpheus love so much?', ['His wife.', 'The consul.', 'A centurion.', 'The merchant.'], 'His wife.', 'Uxorem means his wife. Ita amabat ut introduces the result of that love.', { passageId: 'intermediate-reading-orpheus', order: 4 }),
  annualExamQ('ir-sch-05', 'intermediate-reading', 'reading', 'Where did that love take Orpheus?', ['To the underworld.', 'To Ostia.', 'To the hot room of the baths.', 'To Alexandria.'], 'To the underworld.', 'Ad inferos descenderet means he went down to the underworld. Inferos means those below.', { passageId: 'intermediate-reading-orpheus', order: 5 }),
  annualExamQ('ir-sch-06', 'intermediate-reading', 'reading', 'What did the boys ask?', ['Whether Orpheus had brought his wife back.', 'Where the Tiber was.', 'How much the bread cost.', 'Who founded Rome.'], 'Whether Orpheus had brought his wife back.', 'Num Orpheus uxorem reduxisset asks whether he had brought his wife back. Reduxisset is pluperfect subjunctive.', { passageId: 'intermediate-reading-orpheus', order: 6 }),
  annualExamQ('ir-sch-07', 'intermediate-reading', 'reading', 'A question with num expects', ['the answer no.', 'the answer yes.', 'a place name only.', 'a Roman numeral.'], 'the answer no.', 'Num introduces a question that expects no. Nonne would expect yes. The boys doubt that Orpheus succeeded.', { passageId: 'intermediate-reading-orpheus', order: 7 }),
  annualExamQ('ir-sch-08', 'intermediate-reading', 'reading', 'What does the teacher say happened?', ['Orpheus looked back and lost his wife.', 'Orpheus became king.', 'The wife stayed in Rome.', 'The boys found the wife.'], 'Orpheus looked back and lost his wife.', 'Eum respexisse et uxorem amisisse means that he looked back and lost his wife.', { passageId: 'intermediate-reading-orpheus', order: 8 }),
  annualExamQ('ir-sch-09', 'intermediate-reading', 'reading', 'Respexisse is', ['a perfect infinitive: to have looked back.', 'a present command.', 'a dative noun.', 'a future participle.'], 'a perfect infinitive: to have looked back.', 'Respexisse is the perfect infinitive of respicio. After respondit it reports a completed action.', { passageId: 'intermediate-reading-orpheus', order: 9 }),
  annualExamQ('ir-sch-10', 'intermediate-reading', 'reading', 'What does Lucius say he wants?', ['To learn a song too.', 'To leave Rome.', 'To buy a ship.', 'To become consul.'], 'To learn a song too.', 'Se carmen discere velle means that he wanted to learn a song. Quoque means also.', { passageId: 'intermediate-reading-orpheus', order: 10 }),
  annualExamQ('ir-sch-11', 'intermediate-reading', 'reading', 'Se in Lucius\'s sentence refers to', ['Lucius.', 'the teacher.', 'Orpheus.', 'the wife.'], 'Lucius.', 'Se refers to the subject of dixit, Lucius. He says that he himself wants to learn a song.', { passageId: 'intermediate-reading-orpheus', order: 11 }),
  annualExamQ('ir-sch-12', 'intermediate-reading', 'reading', 'What does the teacher show him?', ['A lyre.', 'A sword.', 'A map of Ostia.', 'A letter from Caesar.'], 'A lyre.', 'Lyram means a lyre. Monstravit means he showed.', { passageId: 'intermediate-reading-orpheus', order: 12 }),
  annualExamQ('ir-sch-13', 'intermediate-reading', 'reading', 'Ei in "Magister ei lyram monstravit" is', ['dative: to him.', 'nominative: the teacher.', 'accusative: the lyre.', 'ablative: by a song.'], 'dative: to him.', 'Ei is the dative of is. The teacher showed the lyre to him. Lyram is the direct object.', { passageId: 'intermediate-reading-orpheus', order: 13 }),
  annualExamQ('ir-sch-14', 'intermediate-reading', 'reading', 'What command does the teacher give?', ['Sing, boys.', 'Go to the river.', 'Do not look back.', 'Write a letter.'], 'Sing, boys.', 'Canite is the plural command of cano, sing. Pueri is vocative, boys.', { passageId: 'intermediate-reading-orpheus', order: 14 }),
  annualExamQ('ir-sch-15', 'intermediate-reading', 'reading', 'When do the boys go home?', ['When the song had been finished.', 'Before the story begins.', 'At midnight only.', 'When the enemy crosses.'], 'When the song had been finished.', 'Cum carmen finitum esset means when the song had been finished. Finitum esset is passive.', { passageId: 'intermediate-reading-orpheus', order: 15 }),
  annualExamQ('ir-sch-16', 'intermediate-reading', 'reading', 'How do the boys go home?', ['Happy.', 'Afraid and lost.', 'By ship to Egypt.', 'Without the teacher\'s permission, and angry.'], 'Happy.', 'Laeti agrees with pueri. Domum redierunt means they returned home.', { passageId: 'intermediate-reading-orpheus', order: 16 }),
  annualExamQ('ir-sch-17', 'intermediate-reading', 'reading', 'Domum in the last sentence means', ['homeward.', 'the master.', 'a gift.', 'at night.'], 'homeward.', 'Domum is the accusative used for place to which: home. It does not need a preposition.', { passageId: 'intermediate-reading-orpheus', order: 17 }),

  annualExamQ('ir-ext-01', 'intermediate-reading', 'mythology', 'The teacher\'s story ends when Orpheus loses his wife. In the myth her name is', ['Eurydice.', 'Dido.', 'Lavinia.', 'Helen.'], 'Eurydice.', 'The passage calls her uxor, wife, and does not give the name. The myth names her Eurydice. Orpheus loses her when he looks back.', { section: 'extension', passageId: 'intermediate-reading-orpheus', order: 1 }),
  annualExamQ('ir-ext-02', 'intermediate-reading', 'geography', 'The farmer lives near the Tiber and the ships come from Ostia. The Tiber flows through Rome and reaches the sea at', ['Ostia.', 'Alexandria.', 'Athens.', 'Carthage.'], 'Ostia.', 'The passage sends grain from Ostia to Rome. Ostia stood at the mouth of the Tiber, Rome\'s river.', { section: 'extension', passageId: 'intermediate-reading-tiber', order: 1 }),
  annualExamQ('ir-ext-03', 'intermediate-reading', 'culture', 'The boys sit in schola and listen to a magister. A common writing surface in a Roman school was', ['a wax tablet.', 'a printed book.', 'a glass window.', 'a steel pen only.'], 'a wax tablet.', 'The passage is a school scene. Students often wrote on wooden tablets coated with wax, using a stylus. The teacher in the story is the magister.', { section: 'extension', passageId: 'intermediate-reading-orpheus', order: 2 }),
  annualExamQ('ir-ext-04', 'intermediate-reading', 'history', 'Gaius and his father sell frumentum in Rome. Grain mattered to the city because', ['Rome depended on imported grain to feed its people.', 'Romans refused to eat bread.', 'grain was used only for ink.', 'the senate met in a bakery.'], 'Rome depended on imported grain to feed its people.', 'The passage brings grain from Ostia to Rome. The city\'s food supply, later called the annona, depended on grain shipped in from overseas.', { section: 'extension', passageId: 'intermediate-reading-tiber', order: 2 }),

  annualExamQ('ap-gram-01', 'advanced-prose', 'grammar', 'Epistula lecta is an ablative absolute. It means', ['after the letter had been read.', 'the letter is the direct object.', 'he reads to the letter.', 'because of a long speech.'], 'after the letter had been read.', 'A noun and a participle in the ablative can stand apart from the main grammar. Epistula lecta means with the letter having been read.'),
  annualExamQ('ap-gram-02', 'advanced-prose', 'grammar', 'In "ponte utuntur," ponte is ablative because', ['utor takes the ablative.', 'pons is the subject.', 'the verb is a command.', 'ponte shows motion toward.'], 'utor takes the ablative.', 'Utor, frui, fungi, potiri, and vesci take the ablative. Ponte utuntur means they use the bridge.'),
  annualExamQ('ap-gram-03', 'advanced-prose', 'grammar', 'Ne hostes flumen transeant means', ['so that the enemy may not cross the river.', 'that the enemy did not cross yesterday.', 'if the enemy had crossed.', 'the enemy are crossing now.'], 'so that the enemy may not cross the river.', 'Ne plus the subjunctive is a negative purpose clause. Transeant is present subjunctive of transeo.'),
  annualExamQ('ap-gram-04', 'advanced-prose', 'grammar', 'In "rogat cur hostes appropinquent," appropinquent is subjunctive because', ['cur introduces an indirect question.', 'the soldiers are commanding the enemy.', 'appropinquo is always subjunctive.', 'the clause is an ablative absolute.'], 'cur introduces an indirect question.', 'A question inside a statement takes the subjunctive. Cur appropinquent asks why they are approaching.'),
  annualExamQ('ap-gram-05', 'advanced-prose', 'grammar', 'Eos frumentum cupere is an indirect statement meaning', ['that they want grain.', 'that grain wants them.', 'to have wanted grain long ago only.', 'do not want grain.'], 'that they want grain.', 'The subject of the infinitive cupere is the accusative eos. After respondit, the present infinitive says what they want at the time of the reply.'),
  annualExamQ('ap-gram-06', 'advanced-prose', 'grammar', '"Nisi vos adfuissetis, hostes transissent" means', ['if you had not been there, the enemy would have crossed.', 'if you are here, the enemy is crossing.', 'you were there, so the enemy crossed.', 'unless you leave, stay.'], 'if you had not been there, the enemy would have crossed.', 'Pluperfect subjunctives in both clauses make a past contrary-to-fact condition. Adfuissetis is from adsum, and transissent is from transeo.'),
  annualExamQ('ap-gram-07', 'advanced-prose', 'grammar', 'What does loquitur mean?', ['He speaks.', 'He is spoken.', 'He spoke yesterday only.', 'To have been said.'], 'He speaks.', 'Loquor is a deponent verb: it has passive forms and active meaning. Loquitur is present, he speaks.'),
  annualExamQ('ap-gram-08', 'advanced-prose', 'grammar', 'In "meminit veteris amici," veteris amici is genitive because', ['memini often takes the genitive of a person remembered.', 'the friend is the subject.', 'memini is passive.', 'the phrase shows the means.'], 'memini often takes the genitive of a person remembered.', 'Meminit means he remembers. A person remembered is commonly in the genitive: veteris amici, of an old friend.'),
  annualExamQ('ap-gram-09', 'advanced-prose', 'grammar', 'In "ars legendi," legendi is', ['a gerund: of reading.', 'a future imperative.', 'the nominative subject.', 'an ablative absolute.'], 'a gerund: of reading.', 'Legendi is the genitive of the gerund of lego. Ars legendi means the art of reading. A gerund is a verbal noun.'),
  annualExamQ('ap-gram-10', 'advanced-prose', 'grammar', 'Timeo ne hostes veniant means', ['I fear that the enemy may come.', 'I fear that the enemy may not come.', 'I do not fear the enemy.', 'I order the enemy to come.'], 'I fear that the enemy may come.', 'After a verb of fearing, ne introduces the fear that something will happen. Timeo ut, or timeo ne non, fears that it will not happen.'),
  annualExamQ('ap-gram-11', 'advanced-prose', 'grammar', '"Tam fortis est ut omnes eum laudent" means', ['he is so brave that everyone praises him.', 'he is brave in order to praise everyone.', 'he was so brave that he left.', 'everyone is braver than he is.'], 'he is so brave that everyone praises him.', 'Tam ... ut with the subjunctive is a result clause. Laudent is present subjunctive, they praise.'),
  annualExamQ('ap-gram-12', 'advanced-prose', 'grammar', 'Cum hostes appropinquarent, milites pontem tenebant means', ['when the enemy were approaching, the soldiers were holding the bridge.', 'because the soldiers had already left.', 'if the enemy come, leave the bridge.', 'the enemy hold the soldiers.'], 'when the enemy were approaching, the soldiers were holding the bridge.', 'Cum with the imperfect subjunctive sets the circumstances. Tenebant is imperfect indicative, they were holding.'),

  annualExamQ('ap-voc-01', 'advanced-prose', 'vocabulary', 'Ripa means', ['bank of a river.', 'bridge.', 'camp.', 'letter.'], 'bank of a river.', 'Ripa means the bank of a river. Pons is the bridge, and castra is the camp.'),
  annualExamQ('ap-voc-02', 'advanced-prose', 'vocabulary', 'Castra means', ['a military camp.', 'a law court only.', 'a wedding veil.', 'a poem.'], 'a military camp.', 'Castra is a plural noun meaning camp. In castra means into the camp.'),
  annualExamQ('ap-voc-03', 'advanced-prose', 'vocabulary', 'Frumentum means', ['grain.', 'sword.', 'bridge.', 'speech.'], 'grain.', 'Frumentum means grain. The soldiers in these passages guard the grain supply.'),
  annualExamQ('ap-voc-04', 'advanced-prose', 'vocabulary', 'Oratio means', ['a speech.', 'a shore.', 'a ship.', 'a gate.'], 'a speech.', 'Oratio means a speech. Orator is the speaker. Cicero\'s orationes are his speeches.'),

  annualExamQ('ap-der-01', 'advanced-prose', 'derivatives', 'Subsequent comes from subsequor and means', ['following after.', 'leading before.', 'unable to speak.', 'falling from a tree.'], 'following after.', 'Sub means under or after, and sequor means to follow. A subsequent event follows another.'),
  annualExamQ('ap-der-02', 'advanced-prose', 'derivatives', 'Loquacious comes from loquor and describes someone who is', ['talkative.', 'silent.', 'warlike.', 'made of iron.'], 'talkative.', 'Loquor means to speak. Loquax means talkative, and loquacious is the English derivative.'),
  annualExamQ('ap-der-03', 'advanced-prose', 'derivatives', 'Deciduous comes from decido, de and cado, and describes something that', ['falls off, such as leaves.', 'cannot be escaped.', 'lives in a city.', 'speaks for a long time.'], 'falls off, such as leaves.', 'Cado means to fall, and de means down from. Deciduous trees drop their leaves.'),
  annualExamQ('ap-der-04', 'advanced-prose', 'derivatives', 'Magnanimous comes from magnus and animus and means', ['great-souled, generous.', 'small-minded.', 'loud-voiced.', 'short-lived.'], 'great-souled, generous.', 'Magnus means great, and animus means spirit or mind. A magnanimous person has a generous spirit.'),

  annualExamQ('ap-mot-01', 'advanced-prose', 'mottoes', 'Habeas corpus means', ['you shall have the body.', 'you shall have the field.', 'the body is absent.', 'seize the day.'], 'you shall have the body.', 'Habeas is a subjunctive of habeo, and corpus means body. The phrase names a writ protecting a person from being held without a hearing.'),
  annualExamQ('ap-mot-02', 'advanced-prose', 'mottoes', 'De facto means', ['in fact.', 'by law.', 'from the city.', 'before the war.'], 'in fact.', 'De facto means in fact, or from the fact. De iure means by law. A de facto leader holds power whether or not the law has named that person.'),
  annualExamQ('ap-mot-03', 'advanced-prose', 'mottoes', 'Suum cuique means', ['to each his own.', 'to each the same punishment.', 'one out of many.', 'time flies.'], 'to each his own.', 'Suum means one\'s own, and cuique is the dative of quisque, to each. The phrase says that each person should receive what is proper.'),
  annualExamQ('ap-mot-04', 'advanced-prose', 'mottoes', 'Morituri te salutamus means', ['we who are about to die salute you.', 'you who are about to die salute us.', 'we have already died.', 'do not salute the dying.'], 'we who are about to die salute you.', 'Morituri means those about to die, and salutamus means we salute. Suetonius quotes gladiators in the third person, morituri te salutant. The familiar motto uses the first person, salutamus.'),

  annualExamQ('ap-oral-01', 'advanced-prose', 'oral', 'Plaudite means', ['applaud.', 'be quiet.', 'let us leave.', 'I am sorry.'], 'applaud.', 'Plaudite is a plural command of plaudo. Roman comedies often ended by asking the audience to applaud.'),
  annualExamQ('ap-oral-02', 'advanced-prose', 'oral', 'Me paenitet means', ['I am sorry.', 'I am well.', 'let us go.', 'wonderful to say.'], 'I am sorry.', 'Paenitet is impersonal. Me paenitet means it causes me regret, or I am sorry. Me is accusative.'),
  annualExamQ('ap-oral-03', 'advanced-prose', 'oral', 'Eamus means', ['let us go.', 'they went.', 'go, to one person.', 'we shall have gone.'], 'let us go.', 'Eamus is the present subjunctive of eo used as a gentle command: let us go.'),

  annualExamQ('ap-myth-01', 'advanced-prose', 'mythology', 'The Parcae, or Fates, are goddesses who', ['spin, measure, and cut the thread of life.', 'guard the underworld gate only as one god.', 'teach the arts as the nine Muses.', 'rule the sea.'], 'spin, measure, and cut the thread of life.', 'Clotho spins the thread, Lachesis measures it, and Atropos cuts it. The Romans called them the Parcae.'),
  annualExamQ('ap-myth-02', 'advanced-prose', 'mythology', 'The Furies punish', ['serious crime, especially crime inside a family.', 'only lost sailors.', 'poets who miss a beat.', 'farmers who sell grain.'], 'serious crime, especially crime inside a family.', 'The Furies, called Furiae or Dirae in Latin, pursue people guilty of terrible crimes such as killing a parent.'),
  annualExamQ('ap-myth-03', 'advanced-prose', 'mythology', 'A centaur has', ['a human upper body and a horse\'s body.', 'one hundred hands.', 'a bull\'s head.', 'wings and a beak.'], 'a human upper body and a horse\'s body.', 'Centaurs are part human and part horse. The hundred-handed giants are the Hecatoncheires, a different group.'),
  annualExamQ('ap-myth-04', 'advanced-prose', 'mythology', 'Janus is the god of', ['beginnings, gates, and doorways.', 'the forge.', 'grain alone.', 'the underworld.'], 'beginnings, gates, and doorways.', 'Janus has two faces, looking forward and back. His month, January, opens the year. The forge belongs to Vulcan.'),

  annualExamQ('ap-hist-01', 'advanced-prose', 'history', 'At Pharsalus in 48 BCE,', ['Caesar defeated Pompey.', 'Octavian defeated Antony.', 'Hannibal defeated the Romans.', 'Romulus founded the city.'], 'Caesar defeated Pompey.', 'Pharsalus was the decisive battle of the civil war between Caesar and Pompey. Pompey then fled to Egypt.'),
  annualExamQ('ap-hist-02', 'advanced-prose', 'history', 'At Philippi in 42 BCE,', ['Antony and Octavian defeated Brutus and Cassius.', 'Caesar crossed the Rubicon.', 'Cicero was consul.', 'Vesuvius erupted.'], 'Antony and Octavian defeated Brutus and Cassius.', 'Philippi ended the cause of Caesar\'s assassins. Brutus and Cassius died after the defeat.'),
  annualExamQ('ap-hist-03', 'advanced-prose', 'history', 'Cicero was consul in 63 BCE, the year of', ['the Catilinarian conspiracy.', 'the battle of Actium.', 'the eruption of Vesuvius.', 'the founding of the Republic.'], 'the Catilinarian conspiracy.', 'As consul in 63 BCE, Cicero exposed Catiline\'s plot and delivered the Catilinarian speeches.'),
  annualExamQ('ap-hist-04', 'advanced-prose', 'history', 'Catiline\'s conspiracy aimed to', ['seize control of Rome.', 'found a new city on the Tiber.', 'translate the Odyssey.', 'build the first aqueduct.'], 'seize control of Rome.', 'Lucius Sergius Catilina plotted to overthrow the government in 63 BCE. Cicero, as consul, worked to stop him.'),

  annualExamQ('ap-geo-01', 'advanced-prose', 'geography', 'Alexandria was a great city in', ['Egypt.', 'Gaul.', 'Britain.', 'Spain.'], 'Egypt.', 'Alexander the Great founded Alexandria in Egypt. It was famous for its library and lighthouse.'),
  annualExamQ('ap-geo-02', 'advanced-prose', 'geography', 'The Alps separate Italy from', ['lands to the north.', 'Egypt.', 'Sicily.', 'the island of Crete only.'], 'lands to the north.', 'The Alps form the northern barrier of Italy. Hannibal\'s crossing of the Alps is one famous march through them.'),
  annualExamQ('ap-geo-03', 'advanced-prose', 'geography', 'Latium is the region', ['around Rome.', 'around Athens.', 'of northern Britain.', 'of the Nile delta.'], 'around Rome.', 'Latium is the district of central Italy in which Rome stands. Latin is the language of Latium.'),

  annualExamQ('ap-life-01', 'advanced-prose', 'culture', 'In the Republic, a consul was', ['one of two chief yearly magistrates.', 'a priest of Vesta only.', 'an enslaved tutor.', 'a gladiator.'], 'one of two chief yearly magistrates.', 'Two consuls were elected each year. They led the state and, in early Rome, the army. The cursus honorum led up to this office.'),
  annualExamQ('ap-life-02', 'advanced-prose', 'culture', 'The Kalends were', ['the first day of the month.', 'the last day of the year only.', 'a military rank.', 'a kind of ship.'], 'the first day of the month.', 'Romans counted dates from the Kalends, the Nones, and the Ides. The Kalends were the first day of each month.'),
  annualExamQ('ap-life-03', 'advanced-prose', 'culture', 'A centurion commanded', ['a century of about 80 to 100 soldiers.', 'the whole senate.', 'a fleet of grain ships only.', 'the Vestal Virgins.'], 'a century of about 80 to 100 soldiers.', 'A centuria was a small unit of the legion, and the centurio was its officer. He was known by the crest across his helmet.'),
  annualExamQ('ap-life-04', 'advanced-prose', 'culture', 'The flammeum was', ['the bride\'s flame-colored veil.', 'the consul\'s chair.', 'a soldier\'s shield.', 'a wax tablet.'], 'the bride\'s flame-colored veil.', 'At a Roman wedding the bride wore a flammeum, a bright orange-yellow veil. The word is related to flamma, flame.'),

  annualExamQ('ap-read-01', 'advanced-prose', 'reading', 'From where had the messenger come down?', ['From the hill.', 'From the underworld.', 'From a ship at Ostia.', 'From the senate house.'], 'From the hill.', 'A colle descenderat means he had come down from the hill. Descenderat is pluperfect.', { passageId: 'advanced-prose-bridge', order: 1 }),
  annualExamQ('ap-read-02', 'advanced-prose', 'reading', 'What does epistula lecta tell you?', ['The commander acts after the letter has been read.', 'The letter is still sealed.', 'The messenger cannot read.', 'The centurions wrote the letter.'], 'The commander acts after the letter has been read.', 'Epistula lecta is an ablative absolute: the letter having been read. Then he calls the centurions.', { passageId: 'advanced-prose-bridge', order: 2 }),
  annualExamQ('ap-read-03', 'advanced-prose', 'reading', 'What does the commander order?', ['Seize the bridge so the enemy may not cross.', 'Burn the camp.', 'Sail to Egypt.', 'Read the letter aloud to the enemy.'], 'Seize the bridge so the enemy may not cross.', 'Occupate means seize. Ne hostes flumen transeant gives the purpose: so that the enemy may not cross the river.', { passageId: 'advanced-prose-bridge', order: 3 }),
  annualExamQ('ap-read-04', 'advanced-prose', 'reading', 'What had the soldiers done before they hurried to the bank?', ['They had taken up their arms.', 'They had crossed to the enemy.', 'They had sold the grain.', 'They had gone home.'], 'They had taken up their arms.', 'Armis sumptis is an ablative absolute: arms having been taken up. Ad ripam contendunt means they hurry to the bank.', { passageId: 'advanced-prose-bridge', order: 4 }),
  annualExamQ('ap-read-05', 'advanced-prose', 'reading', 'What does one soldier ask?', ['Why the enemy are approaching so quickly.', 'Where Rome is.', 'Who wrote the Aeneid.', 'Whether the bridge is wood or stone only.'], 'Why the enemy are approaching so quickly.', 'Cur hostes tam celeriter appropinquent means why the enemy are approaching so quickly.', { passageId: 'advanced-prose-bridge', order: 5 }),
  annualExamQ('ap-read-06', 'advanced-prose', 'reading', 'What reason does the commander give?', ['The enemy want grain.', 'The enemy want a wedding.', 'The enemy are lost sailors.', 'The enemy are bringing a letter of peace.'], 'The enemy want grain.', 'Eos frumentum cupere means that they want grain. Cupere is the infinitive of cupio.', { passageId: 'advanced-prose-bridge', order: 6 }),
  annualExamQ('ap-read-07', 'advanced-prose', 'reading', 'What do the soldiers do at night?', ['They use the bridge and guard the river.', 'They sleep in the forum.', 'They return the letter unopened.', 'They join the enemy.'], 'They use the bridge and guard the river.', 'Ponte utuntur means they use the bridge. Ponte is ablative with utor. Flumen custodiunt means they guard the river.', { passageId: 'advanced-prose-bridge', order: 7 }),
  annualExamQ('ap-read-08', 'advanced-prose', 'reading', 'What happens at first light?', ['The enemy come to the bridge, but the soldiers drive them back.', 'The messenger returns to the hill.', 'The bridge falls.', 'The commander surrenders.'], 'The enemy come to the bridge, but the soldiers drive them back.', 'Prima luce means at dawn. Eos repellunt means they drive them back.', { passageId: 'advanced-prose-bridge', order: 8 }),
  annualExamQ('ap-read-09', 'advanced-prose', 'reading', 'Why does the commander praise the soldiers?', ['Because they held the bridge bravely.', 'Because they fled.', 'Because they burned the grain.', 'Because they read Greek.'], 'Because they held the bridge bravely.', 'Quod pontem fortiter tenuerunt means because they held the bridge bravely. Tenuerunt is perfect of teneo.', { passageId: 'advanced-prose-bridge', order: 9 }),
  annualExamQ('ap-read-10', 'advanced-prose', 'reading', 'What does the commander say would have happened if the soldiers had not been there?', ['The enemy would have crossed the river.', 'The city would have been founded.', 'The letter would have been longer.', 'The hill would have disappeared.'], 'The enemy would have crossed the river.', 'Nisi vos adfuissetis, hostes flumen transissent: if you had not been present, the enemy would have crossed the river.', { passageId: 'advanced-prose-bridge', order: 10 }),

  annualExamQ('ay-gram-01', 'advanced-poetry', 'grammar', 'A dactyl is', ['one long syllable and two short syllables.', 'two long syllables.', 'three short syllables.', 'one short syllable and two long syllables.'], 'one long syllable and two short syllables.', 'A dactyl is long-short-short. The word dactylus means finger, which has one long joint and two short ones.'),
  annualExamQ('ay-gram-02', 'advanced-poetry', 'grammar', 'A spondee is', ['two long syllables.', 'one long and two short syllables.', 'two short syllables.', 'three long syllables.'], 'two long syllables.', 'A spondee is long-long. In hexameter it may replace a dactyl in most feet.'),
  annualExamQ('ay-gram-03', 'advanced-poetry', 'grammar', 'A line of dactylic hexameter has', ['six feet.', 'five feet.', 'four feet.', 'eight feet.'], 'six feet.', 'Hexameter means six measures. The fifth foot is almost always a dactyl, and the sixth is a spondee or a trochee.'),
  annualExamQ('ay-gram-04', 'advanced-poetry', 'grammar', 'The fifth foot of a dactylic hexameter is usually', ['a dactyl.', 'a single short syllable.', 'a trochee of three longs.', 'omitted.'], 'a dactyl.', 'Poets rarely put a spondee in the fifth foot. A line that does so is called spondaic.'),
  annualExamQ('ay-gram-05', 'advanced-poetry', 'grammar', 'An elegiac couplet consists of', ['a dactylic hexameter followed by a pentameter.', 'two pentameters.', 'a Sapphic stanza.', 'six dactyls and nothing else.'], 'a dactylic hexameter followed by a pentameter.', 'The elegiac couplet is the meter of love poetry and epitaphs. Ovid uses it in the Amores. The second line has a strong break in the middle.'),
  annualExamQ('ay-gram-06', 'advanced-poetry', 'grammar', 'Elision happens when', ['a word ending in a vowel, or a vowel plus m, meets a word beginning with a vowel or h.', 'two consonants meet.', 'a line has six feet.', 'a poet repeats a word.'], 'a word ending in a vowel, or a vowel plus m, meets a word beginning with a vowel or h.', 'The final vowel or the syllable -m is slurred. H does not stop elision. Poets sometimes refuse elision; that gap is called hiatus.'),
  annualExamQ('ay-gram-07', 'advanced-poetry', 'grammar', 'Which pattern is chiasmus?', ['Adjective, noun, noun, adjective.', 'The same word beginning three lines.', 'A comparison using sicut.', 'A word that imitates a sound.'], 'Adjective, noun, noun, adjective.', 'Chiasmus is ABBA order, named for the Greek letter chi. Magnae urbes, fora parva puts adjective, noun, noun, adjective.'),
  annualExamQ('ay-gram-08', 'advanced-poetry', 'grammar', 'Synchysis is', ['interlocking ABAB word order.', 'ABBA word order.', 'the omission of every verb.', 'a pause in the third foot only.'], 'interlocking ABAB word order.', 'Synchysis weaves pairs together, as in adjective, adjective, noun, noun, or A B A B. Chiasmus is the crossed order A B B A.'),
  annualExamQ('ay-gram-09', 'advanced-poetry', 'grammar', 'Litotes is', ['saying something by denying its opposite.', 'a comparison with velut.', 'repetition at the start of lines.', 'a word such as murmur.'], 'saying something by denying its opposite.', 'Non parvus can mean great. The speaker denies the opposite of what is meant. Litotes is a form of understatement.'),
  annualExamQ('ay-gram-10', 'advanced-poetry', 'grammar', 'Anaphora is', ['repetition of a word at the beginning of successive phrases.', 'ABBA word order.', 'a metaphor.', 'elision of a final m.'], 'repetition of a word at the beginning of successive phrases.', 'Anaphora repeats an opening word. Filia per silvas at the start of two lines in the reading passage is anaphora.'),
  annualExamQ('ay-gram-11', 'advanced-poetry', 'grammar', 'A simile differs from a metaphor because a simile', ['uses a comparing word such as sicut, velut, or qualis.', 'never involves an animal.', 'must be one word.', 'is always a verb.'], 'uses a comparing word such as sicut, velut, or qualis.', 'A metaphor says one thing is another. A simile makes the comparison with a word such as sicut or velut, like or as.'),
  annualExamQ('ay-gram-12', 'advanced-poetry', 'grammar', 'Onomatopoeia is', ['a word that imitates a sound.', 'a line of six feet.', 'a Greek accusative.', 'a patron of poets.'], 'a word that imitates a sound.', 'Murmur imitates a low sound, and the device is called onomatopoeia. The word itself is Greek for name-making.'),
  annualExamQ('ay-gram-13', 'advanced-poetry', 'grammar', 'Aenean is', ['a Greek accusative of Aeneas.', 'the genitive of Aeneas.', 'a verb meaning he sings.', 'the vocative of Anna.'], 'a Greek accusative of Aeneas.', 'Aeneas can have the Latin accusative Aeneam or the Greek accusative Aenean. Poets often use the Greek form.'),
  annualExamQ('ay-gram-14', 'advanced-poetry', 'grammar', 'Amasti is a poetic shortening of', ['amavisti.', 'amabitis.', 'amatus est.', 'amatis.'], 'amavisti.', 'Poets often drop a syllable in a perfect form. Amasti stands for amavisti, you loved. Norat can stand for noverat, he knew.'),
  annualExamQ('ay-gram-15', 'advanced-poetry', 'grammar', 'A caesura is', ['a word-break inside a foot.', 'the last syllable of the line only.', 'elision of h.', 'a spondee in the fifth foot.'], 'a word-break inside a foot.', 'A caesura is a pause where one word ends and another begins inside a metrical foot. Hexameter often has a caesura in the third foot.'),

  annualExamQ('ay-voc-01', 'advanced-poetry', 'vocabulary', 'Vates means', ['poet or prophet.', 'soldier.', 'bridge.', 'law.'], 'poet or prophet.', 'Vates is a poet, especially one who speaks with inspired authority. Vergil uses it of poets and prophets.'),
  annualExamQ('ay-voc-02', 'advanced-poetry', 'vocabulary', 'Nemus means', ['grove.', 'ship.', 'sword.', 'city.'], 'grove.', 'Nemus, nemoris means a grove or wooded pasture. Silva is the more general word for woods.'),
  annualExamQ('ay-voc-03', 'advanced-poetry', 'vocabulary', 'Carmen means', ['song or poem.', 'camp.', 'horn only.', 'door.'], 'song or poem.', 'Carmen, carminis means a song or poem. Canere means to sing.'),

  annualExamQ('ay-der-01', 'advanced-poetry', 'derivatives', 'Ineluctable comes from eluctor and means', ['inescapable.', 'easy to say.', 'full of stars.', 'newly born.'], 'inescapable.', 'Eluctor means to struggle out. The prefix in- makes it negative. An ineluctable fate cannot be struggled out of.'),
  annualExamQ('ay-der-02', 'advanced-poetry', 'derivatives', 'Stellar comes from stella and means', ['of a star.', 'of the sea.', 'of iron.', 'of a wound.'], 'of a star.', 'Stella means star. Stellar describes something that has to do with stars.'),
  annualExamQ('ay-der-03', 'advanced-poetry', 'derivatives', 'Progeny comes from progigno and means', ['offspring.', 'a speech.', 'a belt.', 'a backward look.'], 'offspring.', 'Progigno means to bring forth. Progenies is offspring, and progeny is the English word.'),

  annualExamQ('ay-mot-01', 'advanced-poetry', 'mottoes', 'In medias res means', ['into the middle of things.', 'into the middle of the sea.', 'against the law.', 'after the war.'], 'into the middle of things.', 'Medias agrees with res, things. The phrase describes a story that begins in the middle of the action. Horace discusses this way of beginning in the Ars Poetica.'),
  annualExamQ('ay-mot-02', 'advanced-poetry', 'mottoes', 'Dux femina facti means', ['a woman was the leader of the deed.', 'a man was the leader of the woman.', 'the deed led the army.', 'fact follows the leader.'], 'a woman was the leader of the deed.', 'Dux means leader, femina means woman, and facti is the genitive of factum, of the deed. Vergil uses the line of Dido in Aeneid 1.'),
  annualExamQ('ay-mot-03', 'advanced-poetry', 'mottoes', 'Festina lente means', ['make haste slowly.', 'hurry at full speed.', 'the die is cast.', 'while I breathe, I hope.'], 'make haste slowly.', 'Festina is a command of festino, hurry, and lente means slowly. The saying, linked with Augustus, praises careful speed.'),

  annualExamQ('ay-oral-01', 'advanced-poetry', 'oral', 'Mirabile dictu means', ['wonderful to tell.', 'terrible to see.', 'let us sing.', 'hail and farewell.'], 'wonderful to tell.', 'Mirabile means wonderful, and dictu is the ablative supine of dico: in the telling. The phrase marks something amazing.'),
  annualExamQ('ay-oral-02', 'advanced-poetry', 'oral', 'Salvus sis means', ['may you be well.', 'you are a slave.', 'save the city.', 'he was safe.'], 'may you be well.', 'Sis is the subjunctive of sum, and salvus means safe or well. The phrase is a wish used as a greeting.'),
  annualExamQ('ay-oral-03', 'advanced-poetry', 'oral', 'Ave atque vale means', ['hail and farewell.', 'come and see.', 'sing and dance.', 'read and write.'], 'hail and farewell.', 'Ave greets someone, and vale says goodbye. Catullus closes the poem at his brother\'s tomb with ave atque vale.'),

  annualExamQ('ay-myth-01', 'advanced-poetry', 'mythology', 'While fleeing Apollo, Daphne was turned into', ['a laurel tree.', 'a star.', 'a spring only.', 'a white cow.'], 'a laurel tree.', 'In Ovid\'s story, Daphne becomes a laurel, the laurus. Apollo claims the laurel as his tree.'),
  annualExamQ('ay-myth-02', 'advanced-poetry', 'mythology', 'Pyramus and Thisbe spoke', ['through a crack in the wall between their houses.', 'from opposite ends of a battlefield.', 'only after they became birds.', 'on a ship to Troy.'], 'through a crack in the wall between their houses.', 'Ovid tells how Pyramus and Thisbe, whose parents forbade the match, talked through a crack in the wall.'),
  annualExamQ('ay-myth-03', 'advanced-poetry', 'mythology', 'The Muses are', ['goddesses of poetry and the arts.', 'the three Fates.', 'wind gods.', 'river nymphs only.'], 'goddesses of poetry and the arts.', 'Nine Muses, daughters of Memory in the usual account, inspire poetry, music, and the other arts. Poets call on them at the start of an epic.'),
  annualExamQ('ay-myth-04', 'advanced-poetry', 'mythology', 'Orpheus went to the underworld to bring back', ['Eurydice.', 'Dido.', 'Helen.', 'Penelope.'], 'Eurydice.', 'Orpheus played his lyre for the powers below so that Eurydice might follow him. He lost her when he looked back.'),

  annualExamQ('ay-hist-01', 'advanced-poetry', 'history', 'The battle of Actium, in 31 BCE, was the victory of', ['Octavian over Antony and Cleopatra.', 'Caesar over Pompey.', 'Hannibal over Rome.', 'Romulus over Remus.'], 'Octavian over Antony and Cleopatra.', 'Actium, off the western coast of Greece, left Octavian master of the Roman world. He later took the name Augustus.'),
  annualExamQ('ay-hist-02', 'advanced-poetry', 'history', 'Maecenas is remembered as', ['a patron of Vergil and Horace.', 'the last king of Rome.', 'a consul who killed Caesar.', 'the founder of Carthage.'], 'a patron of Vergil and Horace.', 'Gaius Maecenas was a close adviser of Augustus and a supporter of poets, including Vergil and Horace.'),
  annualExamQ('ay-hist-03', 'advanced-poetry', 'history', 'Augustus sent Ovid away to', ['Tomis, on the Black Sea.', 'Athens.', 'Alexandria only.', 'Mantua.'], 'Tomis, on the Black Sea.', 'In 8 CE Augustus exiled Ovid to Tomis, modern Constanta. Ovid wrote the Tristia about that exile.'),

  annualExamQ('ay-geo-01', 'advanced-poetry', 'geography', 'Vergil was born near', ['Mantua.', 'Sulmo.', 'Venusia.', 'Alexandria.'], 'Mantua.', 'Publius Vergilius Maro was born near Mantua, in northern Italy. He later set the Eclogues in an imagined countryside.'),
  annualExamQ('ay-geo-02', 'advanced-poetry', 'geography', 'Ovid was born at', ['Sulmo.', 'Mantua.', 'Verona.', 'Carthage.'], 'Sulmo.', 'Ovid says he was born at Sulmo, in the mountains of central Italy. Sulmo is modern Sulmona.'),
  annualExamQ('ay-geo-03', 'advanced-poetry', 'geography', 'Catullus was from', ['Verona.', 'Tomis.', 'Sparta.', 'Ostia.'], 'Verona.', 'Gaius Valerius Catullus was from Verona in northern Italy. He also writes of his family place at Sirmio.'),

  annualExamQ('ay-life-01', 'advanced-poetry', 'culture', 'Vergil\'s Aeneid is', ['an epic in dactylic hexameter.', 'a comedy in iambs.', 'a set of love letters in prose.', 'a history of the Punic Wars in elegiac couplets.'], 'an epic in dactylic hexameter.', 'The Aeneid tells the story of Aeneas in twelve books of dactylic hexameter. It was left unfinished at Vergil\'s death in 19 BCE.'),
  annualExamQ('ay-life-02', 'advanced-poetry', 'culture', 'Ovid\'s Metamorphoses is written in', ['dactylic hexameter.', 'elegiac couplets.', 'Sapphic stanzas.', 'prose.'], 'dactylic hexameter.', 'The Metamorphoses is a long mythological poem in hexameter. Ovid\'s Amores, by contrast, are elegiac couplets.'),
  annualExamQ('ay-life-03', 'advanced-poetry', 'culture', 'Horace\'s Odes are mainly in', ['lyric meters such as the Alcaic and Sapphic stanzas.', 'prose sentences.', 'the meter of Plautus\'s comedies only.', 'a single elegiac couplet repeated.'], 'lyric meters such as the Alcaic and Sapphic stanzas.', 'The Odes use Greek lyric meters. Horace\'s Satires and Epistles are in hexameter, but the Odes are not.'),
  annualExamQ('ay-life-04', 'advanced-poetry', 'culture', 'Plautus and Terence wrote', ['Roman comedies.', 'epic poems about Actium.', 'the Twelve Tables.', 'handbooks of farming only.'], 'Roman comedies.', 'Plautus and Terence adapted Greek New Comedy for the Roman stage. Terence, brought to Rome from Carthage, wrote in a more even style than Plautus.'),
  annualExamQ('ay-life-05', 'advanced-poetry', 'culture', 'Homer matters to Latin poetry because', ['Vergil takes the Iliad and the Odyssey as models for the Aeneid.', 'Homer wrote the Aeneid in Latin.', 'Homer was Augustus\'s patron.', 'Homer invented elegiac couplets for Ovid.'], 'Vergil takes the Iliad and the Odyssey as models for the Aeneid.', 'Homer is the Greek poet of the Iliad and the Odyssey. He did not write in Latin. Vergil shapes Aeneas\'s story with those epics in view.'),
  annualExamQ('ay-life-06', 'advanced-poetry', 'culture', 'Catullus\'s short poems include', ['poems addressed to Lesbia, in several meters.', 'only one twelve-book epic.', 'the official laws of the kings.', 'a prose history of Alexander.'], 'poems addressed to Lesbia, in several meters.', 'Catullus writes about Lesbia in lyric and elegiac meters. His longer poem 64, on Peleus and Thetis, is in hexameter.'),

  annualExamQ('ay-read-01', 'advanced-poetry', 'reading', 'What came through the woods?', ['The bright light of the moon.', 'A legion.', 'A merchant with bread.', 'A storm from the hill.'], 'The bright light of the moon.', 'Candida lux lunae means the bright light of the moon. Per silvas means through the woods.', { passageId: 'advanced-poetry-moon', order: 1 }),
  annualExamQ('ay-read-02', 'advanced-poetry', 'reading', 'Lunae is', ['genitive: of the moon.', 'dative: to the boy.', 'a verb: it shines.', 'ablative: by a grove.'], 'genitive: of the moon.', 'Lunae is the genitive of luna. Lux lunae means the light of the moon. Candida agrees with lux.', { passageId: 'advanced-poetry-moon', order: 2 }),
  annualExamQ('ay-read-03', 'advanced-poetry', 'reading', 'Venit in this line, with a long e, means', ['came.', 'comes, as a present verb.', 'will come.', 'had wanted.'], 'came.', 'The perfect venit has a long e: vēnit, he or she came. The present venit has a short e. Here the story is past, and the meter needs the long e.', { passageId: 'advanced-poetry-moon', order: 3 }),
  annualExamQ('ay-read-04', 'advanced-poetry', 'reading', 'Where did the moonlight arrive?', ['At the shadows.', 'At the forum.', 'On a ship.', 'In the senate.'], 'At the shadows.', 'Ad umbras means to the shadows. Umbras is accusative plural after ad.', { passageId: 'advanced-poetry-moon', order: 4 }),
  annualExamQ('ay-read-05', 'advanced-poetry', 'reading', 'What was the little boy doing?', ['He was standing and gazing.', 'He was selling grain.', 'He was building a bridge.', 'He was sleeping in camp.'], 'He was standing and gazing.', 'Stabat means he was standing. Mirans is a participle, gazing. Puellus, the little boy, is the subject.', { passageId: 'advanced-poetry-moon', order: 5 }),
  annualExamQ('ay-read-06', 'advanced-poetry', 'reading', 'Mirans agrees with', ['puellus.', 'luna.', 'silvas.', 'umbras.'], 'puellus.', 'Mirans is nominative masculine, like puellus. It does not agree with the feminine lux or the plural silvas.', { passageId: 'advanced-poetry-moon', order: 6 }),
  annualExamQ('ay-read-07', 'advanced-poetry', 'reading', 'Per opaca means', ['through the dark places.', 'under the moon only.', 'without a shadow.', 'toward the city.'], 'through the dark places.', 'Per takes the accusative. Opaca is neuter plural, dark places, used as a noun.', { passageId: 'advanced-poetry-moon', order: 7 }),
  annualExamQ('ay-read-08', 'advanced-poetry', 'reading', 'In silvis means', ['in the woods.', 'into the woods.', 'of the moon.', 'by the boy.'], 'in the woods.', 'Silvis is ablative plural, so in means in. Into the woods would be in silvas.', { passageId: 'advanced-poetry-moon', order: 8 }),
  annualExamQ('ay-read-09', 'advanced-poetry', 'reading', 'The first foot, Candida, is a dactyl because it is', ['long, short, short.', 'long, long.', 'short, short, long.', 'one short syllable.'], 'long, short, short.', 'Can-di-da is long by position, then short, then short. That is a dactyl, and it fills the first foot of the hexameter.', { passageId: 'advanced-poetry-moon', order: 9 }),
  annualExamQ('ay-read-10', 'advanced-poetry', 'reading', 'Each line of the passage is', ['a dactylic hexameter of six feet.', 'a pentameter.', 'a Sapphic stanza.', 'prose with no meter.'], 'a dactylic hexameter of six feet.', 'Both lines scan as dactylic hexameter. A pentameter would be the second line of an elegiac couplet, which this pair is not.', { passageId: 'advanced-poetry-moon', order: 10 }),

  annualExamQ('ar-prose-01', 'advanced-reading', 'reading', 'What had the tired messenger done all night?', ['He had traveled.', 'He had slept in camp.', 'He had read Homer.', 'He had sold the bridge.'], 'He had traveled.', 'Totam noctem iter fecerat means he had traveled for the whole night. Totam noctem is accusative of duration.', { passageId: 'advanced-reading-messenger', order: 1 }),
  annualExamQ('ar-prose-02', 'advanced-reading', 'reading', 'Amicis convocatis means', ['after his friends had been called together.', 'the friends call the messenger.', 'without friends.', 'the friends are the direct object of venit.'], 'after his friends had been called together.', 'This is an ablative absolute. The friends are not the subject of venit. The commander then orders the messenger to speak.', { passageId: 'advanced-reading-messenger', order: 2 }),
  annualExamQ('ar-prose-03', 'advanced-reading', 'reading', 'What is the messenger ordered to say?', ['What he has seen.', 'The names of the Muses.', 'A wedding song.', 'Nothing.'], 'What he has seen.', 'Iubet eum dicere quid viderit means he orders him to say what he has seen. Viderit is subjunctive in the indirect question.', { passageId: 'advanced-reading-messenger', order: 3 }),
  annualExamQ('ar-prose-04', 'advanced-reading', 'reading', 'Where does the messenger say the enemy are?', ['Across the river, and they are making for the bridge.', 'Inside the city already.', 'On the sea at Actium.', 'In the school.'], 'Across the river, and they are making for the bridge.', 'Hostes trans flumen esse et pontem petere means that the enemy are across the river and are seeking the bridge.', { passageId: 'advanced-reading-messenger', order: 4 }),
  annualExamQ('ar-prose-05', 'advanced-reading', 'reading', 'Why must the soldiers defend the bridge?', ['So that the city may not lack grain.', 'So that the enemy may enter at once.', 'So that the messenger can sleep.', 'So that the river may dry up.'], 'So that the city may not lack grain.', 'Ne urbs frumento careat is negative purpose. Careo takes the ablative, so frumento means grain.', { passageId: 'advanced-reading-messenger', order: 5 }),
  annualExamQ('ar-prose-06', 'advanced-reading', 'reading', 'Why is ponti dative in "ponti appropinquant"?', ['Appropinquo takes the dative.', 'Pons is the subject.', 'The soldiers are leaving the bridge.', 'Ponti is a verb.'], 'Appropinquo takes the dative.', 'Appropinquant means they approach. The thing approached, the bridge, is dative: ponti.', { passageId: 'advanced-reading-messenger', order: 6 }),
  annualExamQ('ar-prose-07', 'advanced-reading', 'reading', 'What is the bridge like?', ['Narrow but strong.', 'Wide and broken.', 'Made of ships.', 'Already captured.'], 'Narrow but strong.', 'Angustus means narrow, and firmus means strong. Sed means but.', { passageId: 'advanced-reading-messenger', order: 7 }),
  annualExamQ('ar-prose-08', 'advanced-reading', 'reading', 'What does the centurion urge the soldiers to do?', ['Fight bravely.', 'Retreat at once.', 'Burn the grain.', 'Call the Muses.'], 'Fight bravely.', 'Hortatur ut fortiter pugnent means he urges them to fight bravely. Hortor is a deponent, so hortatur is active in meaning.', { passageId: 'advanced-reading-messenger', order: 8 }),
  annualExamQ('ar-prose-09', 'advanced-reading', 'reading', 'Telis iactis means', ['after spears had been thrown.', 'while holding no weapons.', 'the spears are the subject of conantur.', 'before any spear existed.'], 'after spears had been thrown.', 'Telis iactis is an ablative absolute. Iactis comes from iacio, to throw. Then the enemy try to retreat.', { passageId: 'advanced-reading-messenger', order: 9 }),
  annualExamQ('ar-prose-10', 'advanced-reading', 'reading', 'What do the enemy try to do?', ['Retreat.', 'Found a city.', 'Sing a hymn.', 'Buy the bridge.'], 'Retreat.', 'Se recipere means to retreat, to take oneself back. Conantur means they try. Conor is a deponent.', { passageId: 'advanced-reading-messenger', order: 10 }),
  annualExamQ('ar-prose-11', 'advanced-reading', 'reading', 'What does the commander announce to the citizens?', ['That the enemy have been driven back.', 'That the city has fallen.', 'That the bridge is for sale.', 'That he will leave Rome.'], 'That the enemy have been driven back.', 'Hostes repulsos esse is an indirect statement with a perfect passive infinitive: that the enemy had been driven back.', { passageId: 'advanced-reading-messenger', order: 11 }),
  annualExamQ('ar-prose-12', 'advanced-reading', 'reading', 'Civibus in "nuntiat civibus" is', ['dative: to the citizens.', 'nominative: the commander.', 'accusative: the enemy.', 'a genitive of the city.'], 'dative: to the citizens.', 'Nuntiat takes the dative for the people who receive the news. Civibus means to the citizens.', { passageId: 'advanced-reading-messenger', order: 12 }),
  annualExamQ('ar-prose-13', 'advanced-reading', 'reading', 'What do the citizens give the soldiers?', ['Grain.', 'A crown of laurel only.', 'The command of the camp.', 'Nothing, because they are angry.'], 'Grain.', 'Frumentum militibus donant means they give grain to the soldiers. Militibus is dative.', { passageId: 'advanced-reading-messenger', order: 13 }),
  annualExamQ('ar-prose-14', 'advanced-reading', 'reading', 'Whom do the citizens praise?', ['The commander.', 'The enemy.', 'Orpheus.', 'The merchant in the forum.'], 'The commander.', 'Ducem laudant means they praise the commander. Ducem is accusative.', { passageId: 'advanced-reading-messenger', order: 14 }),
  annualExamQ('ar-prose-15', 'advanced-reading', 'reading', 'Ite in the commander\'s speech is', ['a plural command: go.', 'an infinitive: to have gone.', 'a dative noun.', 'a perfect tense.'], 'a plural command: go.', 'Ite is the plural imperative of eo. Defendite is the plural command that follows: defend.', { passageId: 'advanced-reading-messenger', order: 15 }),
  annualExamQ('ar-prose-16', 'advanced-reading', 'reading', 'Fessus describes', ['the messenger.', 'the bridge.', 'the grain.', 'the citizens.'], 'the messenger.', 'Fessus is nominative masculine and agrees with nuntius. It means tired.', { passageId: 'advanced-reading-messenger', order: 16 }),
  annualExamQ('ar-prose-17', 'advanced-reading', 'reading', 'Trans flumen means', ['across the river.', 'under the river.', 'without a river.', 'of the river.'], 'across the river.', 'Trans takes the accusative and means across. Flumen is accusative. The enemy are on the other side.', { passageId: 'advanced-reading-messenger', order: 17 }),

  annualExamQ('ar-poet-01', 'advanced-reading', 'reading', 'What was the girl doing in the first line?', ['She was running through the woods.', 'She was standing still in the forum.', 'She was sailing.', 'She was reading a letter.'], 'She was running through the woods.', 'Currebat is imperfect, she was running. Per silvas means through the woods.', { passageId: 'advanced-reading-silva', order: 1 }),
  annualExamQ('ar-poet-02', 'advanced-reading', 'reading', 'Where was she running?', ['To the shade of a holm-oak.', 'To the bridge.', 'To Ostia.', 'To the underworld.'], 'To the shade of a holm-oak.', 'Ad ilicis umbram means to the shade of the holm-oak. Ilicis is genitive of ilex.', { passageId: 'advanced-reading-silva', order: 2 }),
  annualExamQ('ar-poet-03', 'advanced-reading', 'reading', 'Ilicis is', ['genitive: of the holm-oak.', 'dative: to the girl.', 'a verb: she flees.', 'ablative: by the moon.'], 'genitive: of the holm-oak.', 'Ilex, ilicis means holm-oak. Ilicis depends on umbram: the shade of the holm-oak. Ad governs umbram, not ilicis.', { passageId: 'advanced-reading-silva', order: 3 }),
  annualExamQ('ar-poet-04', 'advanced-reading', 'reading', 'Whom does the girl call?', ['Her mother.', 'The commander.', 'A sailor.', 'Apollo.'], 'Her mother.', 'Matrem is the accusative of mater. Vocat means she calls.', { passageId: 'advanced-reading-silva', order: 4 }),
  annualExamQ('ar-poet-05', 'advanced-reading', 'reading', 'The tense of vocat is', ['present.', 'imperfect.', 'perfect.', 'future.'], 'present.', 'Vocat is present, she calls. Currebat in the line before is imperfect. A present verb in a past story is a historical present.', { passageId: 'advanced-reading-silva', order: 5 }),
  annualExamQ('ar-poet-06', 'advanced-reading', 'reading', 'Anxia describes', ['the girl.', 'the voice only.', 'the oak.', 'the mother.'], 'the girl.', 'Anxia is nominative feminine and agrees with filia. Voce is a separate ablative. An ablative anxia would have a long final a and would not fit this line.', { passageId: 'advanced-reading-silva', order: 6 }),
  annualExamQ('ar-poet-07', 'advanced-reading', 'reading', 'Voce means', ['with her voice.', 'of her voice.', 'to her voice.', 'the voices, as subject.'], 'with her voice.', 'Voce is ablative of means. She calls with her voice.', { passageId: 'advanced-reading-silva', order: 7 }),
  annualExamQ('ar-poet-08', 'advanced-reading', 'reading', 'The repeated opening Filia per silvas is an example of', ['anaphora.', 'litotes.', 'elision.', 'a pentameter.'], 'anaphora.', 'Anaphora repeats a word or phrase at the beginning. The two lines begin with the same words, Filia per silvas.', { passageId: 'advanced-reading-silva', order: 8 }),
  annualExamQ('ar-poet-09', 'advanced-reading', 'reading', 'Who leads, in the third line?', ['The mother.', 'The girl alone.', 'A little boy.', 'The centurion.'], 'The mother.', 'Mater is the subject of ducit. Natam, the daughter, is the object.', { passageId: 'advanced-reading-silva', order: 9 }),
  annualExamQ('ar-poet-10', 'advanced-reading', 'reading', 'Natam is', ['accusative: the daughter.', 'nominative: the mother.', 'genitive: of the oak.', 'a verb: she swims.'], 'accusative: the daughter.', 'Nata means daughter, and natam is accusative. Ducit takes that object: she leads her daughter.', { passageId: 'advanced-reading-silva', order: 10 }),
  annualExamQ('ar-poet-11', 'advanced-reading', 'reading', 'Per opaca silentia means', ['through the dark, silent places.', 'under a single oak only.', 'without silence.', 'toward the forum.'], 'through the dark, silent places.', 'Per takes the accusative. Opaca silentia is neuter plural: dark silences, or dark silent places.', { passageId: 'advanced-reading-silva', order: 11 }),
  annualExamQ('ar-poet-12', 'advanced-reading', 'reading', 'The first foot of the first line, Filia, is', ['a dactyl.', 'a spondee.', 'a single long syllable.', 'a pentameter.'], 'a dactyl.', 'Fi-li-a is long, short, short. That pattern is a dactyl, and those three syllables are the first foot.', { passageId: 'advanced-reading-silva', order: 12 }),
  annualExamQ('ar-poet-13', 'advanced-reading', 'reading', 'Per in "per silvas" is long by position because', ['its vowel is followed by two consonants, r and s.', 'per is always a diphthong.', 'the poet elides it.', 'silvas is a verb.'], 'its vowel is followed by two consonants, r and s.', 'The e of per is short, but r and the s of silvas follow it. Two consonants make the syllable long. Per sil- is a spondee.', { passageId: 'advanced-reading-silva', order: 13 }),
  annualExamQ('ar-poet-14', 'advanced-reading', 'reading', 'How many feet does each of these lines have?', ['Six.', 'Five.', 'Four.', 'Two.'], 'Six.', 'Each line is a dactylic hexameter, so it has six feet. The fifth foot of each line is a dactyl.', { passageId: 'advanced-reading-silva', order: 14 }),
  annualExamQ('ar-poet-15', 'advanced-reading', 'reading', 'Currebat is', ['imperfect: she was running.', 'present: she runs.', 'perfect: she ran once.', 'a noun: a chariot.'], 'imperfect: she was running.', 'Currebat is the imperfect of curro. It describes the running as going on in the past.', { passageId: 'advanced-reading-silva', order: 15 }),
  annualExamQ('ar-poet-16', 'advanced-reading', 'reading', 'Ducit in the last line is', ['present: she leads.', 'perfect: she led.', 'an infinitive.', 'a participle meaning having led.'], 'present: she leads.', 'Ducit is the present of duco. Like vocat, it is a historical present in this past scene.', { passageId: 'advanced-reading-silva', order: 16 }),

  annualExamQ('ar-ext-01', 'advanced-reading', 'culture', 'The passage mentions a centurio. A centurion was', ['an officer in command of a century.', 'the chief priest of Jupiter.', 'a comic playwright.', 'the bride at a wedding.'], 'an officer in command of a century.', 'The story puts a centurion with the soldiers at the bridge. A century was a small unit of the legion, and the centurion was its commander.', { section: 'extension', passageId: 'advanced-reading-messenger', order: 1 }),
  annualExamQ('ar-ext-02', 'advanced-reading', 'history', 'The city must not lack frumentum. Rome\'s public grain supply was called', ['the annona.', 'the cursus honorum.', 'the flammeum.', 'the toga virilis.'], 'the annona.', 'The passage turns on grain for the city. Annona was the grain supply and its price. Keeping the bridge is, in this story, a way to protect that food.', { section: 'extension', passageId: 'advanced-reading-messenger', order: 2 }),
  annualExamQ('ar-ext-03', 'advanced-reading', 'geography', 'The girl runs to an ilex, a holm-oak. That tree was common in', ['Italy and the lands around the Mediterranean.', 'northern Britain only.', 'the Alps above the snow line only.', 'the Nile delta and nowhere else.'], 'Italy and the lands around the Mediterranean.', 'The passage is set in the woods under a holm-oak. The ilex is an evergreen oak of the Mediterranean, including Italy.', { section: 'extension', passageId: 'advanced-reading-silva', order: 1 }),
  annualExamQ('ar-ext-04', 'advanced-reading', 'mythology', 'The passage is set in the woods. Roman story connects the woodland and the hunt with', ['Diana.', 'Vesta.', 'Janus.', 'Ceres only.'], 'Diana.', 'The lines never name a goddess. Diana, the Greek Artemis, is the goddess of the hunt and of wild places, so a woodland scene can call her to mind.', { section: 'extension', passageId: 'advanced-reading-silva', order: 2 })
]);
